const prisma = new PrismaClient(); const app = express();
const runFile = promisify(execFile) as unknown as (file: string, args: string[], options: { cwd?: string; input: string; timeout: number; maxBuffer: number }) => Promise<{ stdout: string; stderr: string }>;
app.use(cors({ origin: true, credentials: true })); app.use(express.json());
app.get("/", (_req, res) => res.json({ service: "skillsync-api", status: "ok", health: "/api/health" }));
const secret = process.env.JWT_SECRET ?? "development-secret-change-me";
const refreshSecret = process.env.JWT_REFRESH_SECRET ?? "development-refresh-secret-change-me";
const signRefresh = (id: string, role: Role) => jwt.sign({ sub: id, role }, refreshSecret, { expiresIn: "7d" });
const setAuthCookies = (res: express.Response, user: { id: string; role: Role }) => { const access = sign(user.id, user.role); const refresh = signRefresh(user.id, user.role); res.setHeader("Set-Cookie", [`accessToken=${access}; HttpOnly; Path=/; SameSite=Lax; Max-Age=900`, `refreshToken=${refresh}; HttpOnly; Path=/; SameSite=Lax; Max-Age=604800`]); };
const cookieValue = (req: express.Request, name: string) => req.headers.cookie?.split(";").map((item) => item.trim()).find((item) => item.startsWith(`${name}=`))?.slice(name.length + 1);
const requestCounts = new Map<string, { count: number; resetAt: number }>();
app.use((req, res, next) => { const key = req.ip ?? "unknown"; const now = Date.now(); const entry = requestCounts.get(key); if (!entry || entry.resetAt <= now) requestCounts.set(key, { count: 1, resetAt: now + 60_000 }); else { entry.count += 1; if (entry.count > 120) return res.status(429).json({ message: "Too many requests. Try again shortly." }); } res.setHeader("X-Content-Type-Options", "nosniff"); res.setHeader("X-Frame-Options", "DENY"); next(); });
app.use((req, _res, next) => { if (process.env.NODE_ENV !== "test") console.log(JSON.stringify({ method: req.method, path: req.path, at: new Date().toISOString() })); next(); });
const upload = multer({ storage: multer.memoryStorage(), limits: { fileSize: 8 * 1024 * 1024 } });
const sign = (id: string, role: Role) => jwt.sign({ sub: id, role }, secret, { expiresIn: "15m" });
type LocalUser = { id: string; name: string; email: string; passwordHash: string; role: Role };
const localStorePath = path.join(process.cwd(), "data", "local-store.json");
const loadLocalUsers = () => { try { const raw = fs.readFileSync(localStorePath, "utf8"); return new Map<string, LocalUser>(Object.entries(JSON.parse(raw) as Record<string, LocalUser>)); } catch { return new Map<string, LocalUser>(); } };
const localUsers = loadLocalUsers();
const saveLocalUsers = () => { fs.mkdirSync(path.dirname(localStorePath), { recursive: true }); fs.writeFileSync(localStorePath, JSON.stringify(Object.fromEntries(localUsers), null, 2)); };
type LocalCommunityPost = { id: string; authorId: string; content: string; createdAt: string; updatedAt: string; likes: string[]; replies: Array<{ id: string; authorId: string; content: string; createdAt: string }> };
const communityStorePath = path.join(process.cwd(), "data", "community-store.json");
const loadCommunityPosts = () => { try { return JSON.parse(fs.readFileSync(communityStorePath, "utf8")) as LocalCommunityPost[]; } catch { return []; } };
let localCommunityPosts = loadCommunityPosts();
const saveCommunityPosts = () => { fs.mkdirSync(path.dirname(communityStorePath), { recursive: true }); fs.writeFileSync(communityStorePath, JSON.stringify(localCommunityPosts, null, 2)); };
const localAuthor = (id: string) => { const user = [...localUsers.values()].find((item) => item.id === id); return { id, name: user?.name ?? (id === "demo-student" ? "Demo Student" : "SkillSync Student") }; };
const localPostShape = (post: LocalCommunityPost, userId: string) => ({ id: post.id, content: post.content, createdAt: post.createdAt, updatedAt: post.updatedAt, author: localAuthor(post.authorId), replyCount: post.replies.length, likeCount: post.likes.length, liked: post.likes.includes(userId) });
const localAuthFallback = async (req: express.Request, res: express.Response, next: express.NextFunction) => {
  if (process.env.DATABASE_URL) return next();
  if (req.path === "/api/auth/signup" && req.method === "POST") { const data = signupSchema.parse(req.body); if (localUsers.has(data.email)) return res.status(409).json({ message: "Email already registered" }); const user: LocalUser = { id: `local-${Date.now()}`, name: data.name, email: data.email, passwordHash: await bcrypt.hash(data.password, 12), role: data.role }; localUsers.set(user.email, user); saveLocalUsers(); setAuthCookies(res, user); return res.status(201).json({ user: { id: user.id, name: user.name, email: user.email, role: user.role } }); }
  if (req.path === "/api/auth/login" && req.method === "POST") { const data = loginSchema.parse(req.body); let user = localUsers.get(data.email); if (!user && data.email === "student@nxtrot.local" && data.password === "Student@123") { user = { id: "demo-student", name: "Demo Student", email: data.email, passwordHash: await bcrypt.hash(data.password, 12), role: "STUDENT" }; localUsers.set(user.email, user); saveLocalUsers(); } if (!user || !(await bcrypt.compare(data.password, user.passwordHash))) return res.status(401).json({ message: "Invalid credentials" }); setAuthCookies(res, user); return res.json({ user: { id: user.id, name: user.name, email: user.email, role: user.role } }); }
  if (req.path === "/api/auth/me" && req.method === "GET") { const token = cookieValue(req, "accessToken"); if (!token) return res.status(401).json({ message: "Authentication required" }); try { const payload = jwt.verify(token, secret) as { sub: string }; const user = [...localUsers.values()].find((item) => item.id === payload.sub); if (!user) return res.status(401).json({ message: "Session invalid" }); return res.json({ user: { id: user.id, name: user.name, email: user.email, role: user.role } }); } catch { return res.status(401).json({ message: "Session expired" }); } }
  if (req.path === "/api/auth/refresh" && req.method === "POST") { const token = cookieValue(req, "refreshToken"); if (!token) return res.status(401).json({ message: "Refresh token missing" }); try { const payload = jwt.verify(token, refreshSecret) as { sub: string }; const user = [...localUsers.values()].find((item) => item.id === payload.sub); if (!user) return res.status(401).json({ message: "Session invalid" }); setAuthCookies(res, user); return res.json({ refreshed: true }); } catch { return res.status(401).json({ message: "Refresh token expired" }); } }
  return next();
};
app.use(localAuthFallback);
app.get("/api/health", (_req, res) => res.json({ status: "ok", service: "skillsync-api" }));
app.use("/api/community", (req, res, next) => { if (process.env.DATABASE_URL) return next(); const userId = userIdFromRequest(req); const postMatch = req.path.match(/^\/posts\/([^/]+)$/); const replyMatch = req.path.match(/^\/posts\/([^/]+)\/replies$/); const likeMatch = req.path.match(/^\/posts\/([^/]+)\/like$/); if (req.path === "/posts" && req.method === "GET") return res.json({ posts: [...localCommunityPosts].sort((a, b) => b.createdAt.localeCompare(a.createdAt)).map((post) => localPostShape(post, userId)) }); if (req.path === "/posts" && req.method === "POST") { const parsed = communityPostSchema.safeParse(req.body); if (!parsed.success) return res.status(400).json({ message: "Content is required and must be at most 2000 characters" }); const now = new Date().toISOString(); const post: LocalCommunityPost = { id: `community-${Date.now()}`, authorId: userId, content: parsed.data.content, createdAt: now, updatedAt: now, likes: [], replies: [] }; localCommunityPosts = [post, ...localCommunityPosts]; saveCommunityPosts(); return res.status(201).json({ post: localPostShape(post, userId) }); } if (replyMatch && req.method === "GET") { const post = localCommunityPosts.find((item) => item.id === replyMatch[1]); if (!post) return res.status(404).json({ message: "Post not found" }); return res.json({ replies: post.replies.map((reply) => ({ ...reply, author: localAuthor(reply.authorId) })) }); } if (replyMatch && req.method === "POST") { const parsed = communityReplySchema.safeParse(req.body); if (!parsed.success) return res.status(400).json({ message: "Content is required and must be at most 2000 characters" }); const post = localCommunityPosts.find((item) => item.id === replyMatch[1]); if (!post) return res.status(404).json({ message: "Post not found" }); const reply = { id: `reply-${Date.now()}`, authorId: userId, content: parsed.data.content, createdAt: new Date().toISOString() }; post.replies.push(reply); saveCommunityPosts(); return res.status(201).json({ reply: { ...reply, author: localAuthor(userId) } }); } if (likeMatch && req.method === "POST") { const post = localCommunityPosts.find((item) => item.id === likeMatch[1]); if (!post) return res.status(404).json({ message: "Post not found" }); const index = post.likes.indexOf(userId); if (index >= 0) post.likes.splice(index, 1); else post.likes.push(userId); saveCommunityPosts(); return res.json({ liked: index < 0, likeCount: post.likes.length }); } if (postMatch && req.method === "GET") return res.status(404).json({ message: "Post not found" }); return next(); });
const communityPostShape = (post: { id: string; content: string; createdAt: Date; updatedAt: Date; author: { id: string; name: string }; _count: { replies: number; likes: number }; likes: Array<{ userId: string }> }, userId: string) => ({ id: post.id, content: post.content, createdAt: post.createdAt, updatedAt: post.updatedAt, author: post.author, replyCount: post._count.replies, likeCount: post._count.likes, liked: post.likes.some((like) => like.userId === userId) });
app.get("/api/community/posts", async (req, res) => { const userId = userIdFromRequest(req); const posts = await prisma.communityPost.findMany({ orderBy: { createdAt: "desc" }, take: 50, include: { author: { select: { id: true, name: true } }, replies: { select: { id: true } }, likes: { select: { userId: true } }, _count: { select: { replies: true, likes: true } } } }); res.json({ posts: posts.map((post) => communityPostShape(post, userId)) }); });
app.post("/api/community/posts", async (req, res) => { const parsed = communityPostSchema.safeParse(req.body); if (!parsed.success) return res.status(400).json({ message: "Content is required and must be at most 2000 characters" }); const userId = userIdFromRequest(req); const post = await prisma.communityPost.create({ data: { content: parsed.data.content, authorId: userId }, include: { author: { select: { id: true, name: true } }, replies: { select: { id: true } }, likes: { select: { userId: true } }, _count: { select: { replies: true, likes: true } } } }); res.status(201).json({ post: communityPostShape(post, userId) }); });
app.get("/api/community/posts/:postId/replies", async (req, res) => { const replies = await prisma.communityReply.findMany({ where: { postId: req.params.postId }, orderBy: { createdAt: "asc" }, include: { author: { select: { id: true, name: true } } } }); res.json({ replies }); });
app.post("/api/community/posts/:postId/replies", async (req, res) => { const parsed = communityReplySchema.safeParse(req.body); if (!parsed.success) return res.status(400).json({ message: "Content is required and must be at most 2000 characters" }); const post = await prisma.communityPost.findUnique({ where: { id: req.params.postId }, select: { id: true } }); if (!post) return res.status(404).json({ message: "Post not found" }); const reply = await prisma.communityReply.create({ data: { postId: post.id, authorId: userIdFromRequest(req), content: parsed.data.content }, include: { author: { select: { id: true, name: true } } } }); res.status(201).json({ reply }); });
app.post("/api/community/posts/:postId/like", async (req, res) => { const userId = userIdFromRequest(req); const post = await prisma.communityPost.findUnique({ where: { id: req.params.postId }, select: { id: true } }); if (!post) return res.status(404).json({ message: "Post not found" }); const existing = await prisma.communityPostLike.findUnique({ where: { postId_userId: { postId: post.id, userId } } }); if (existing) await prisma.communityPostLike.delete({ where: { id: existing.id } }); else await prisma.communityPostLike.create({ data: { postId: post.id, userId } }); const likeCount = await prisma.communityPostLike.count({ where: { postId: post.id } }); res.json({ liked: !existing, likeCount }); });
const languageConfig: Record<string, { image: string; file: string; command: string[] }> = { python: { image: "python:3.12-alpine", file: "main.py", command: ["python", "/workspace/main.py"] }, c: { image: "gcc:14", file: "main.c", command: ["sh", "-lc", "gcc /workspace/main.c -o /tmp/main && /tmp/main"] }, cpp: { image: "gcc:14", file: "main.cpp", command: ["sh", "-lc", "g++ /workspace/main.cpp -o /tmp/main && /tmp/main"] }, java: { image: "eclipse-temurin:21-jdk", file: "Main.java", command: ["sh", "-lc", "javac /workspace/Main.java && java -cp /workspace Main"] } };
const runLocalProcess = (command: string, args: string[], cwd: string, input: string) => new Promise<{ stdout: string; stderr: string }>((resolve, reject) => { const child = spawn(command, args, { cwd, shell: false, windowsHide: true }); let stdout = ""; let stderr = ""; let settled = false; const finish = (callback: () => void) => { if (!settled) { settled = true; callback(); } }; const timer = setTimeout(() => { child.kill(); finish(() => reject(new Error("timed out"))); }, 5000); child.stdout.on("data", (chunk: Buffer) => { stdout += chunk.toString(); if (stdout.length > 200_000) child.kill(); }); child.stderr.on("data", (chunk: Buffer) => { stderr += chunk.toString(); if (stderr.length > 200_000) child.kill(); }); child.on("error", (error) => { clearTimeout(timer); finish(() => reject(error)); }); child.on("close", (exitCode) => { clearTimeout(timer); finish(() => exitCode === 0 ? resolve({ stdout, stderr }) : reject(new Error(stderr || `Process exited with code ${exitCode}`))); }); child.stdin.write(input); child.stdin.end(); });
const runLocalCode = async (language: string, code: string, input: string) => { const directory = await mkdtemp(`${path.join(os.tmpdir(), "skillsync-code-")}`); try { if (language === "python") { const bundledCandidates = [path.resolve(process.cwd(), "backend", "tools", "python", "python.exe"), path.resolve(process.cwd(), "tools", "python", "python.exe")]; const bundledPython = bundledCandidates.find((candidate) => fs.existsSync(candidate)); if (bundledPython) { await writeFile(path.join(directory, "input.txt"), input, "utf8"); await writeFile(path.join(directory, "runner.py"), `import sys\nsys.stdin = open("input.txt", encoding="utf-8")\n${code}\n`, "utf8"); return runFile(bundledPython, ["runner.py"], { cwd: directory, input: "", timeout: 5000, maxBuffer: 200_000 }); } throw new Error("Python runtime is not installed. Restart the backend from the project root."); } if (language === "c") { await writeFile(path.join(directory, "main.c"), code, "utf8"); await runLocalProcess("gcc", ["main.c", "-O2", "-o", "main.exe"], directory, ""); return runLocalProcess(path.join(directory, "main.exe"), [], directory, input); } if (language === "cpp") { await writeFile(path.join(directory, "main.cpp"), code, "utf8"); await runLocalProcess("g++", ["main.cpp", "-O2", "-o", "main.exe"], directory, ""); return runLocalProcess(path.join(directory, "main.exe"), [], directory, input); } await writeFile(path.join(directory, "Main.java"), code, "utf8"); await runLocalProcess("javac", ["Main.java"], directory, ""); return runLocalProcess("java", ["-cp", directory, "Main"], directory, input); } finally { try { await rm(directory, { recursive: true, force: true }); } catch { setTimeout(() => { void rm(directory, { recursive: true, force: true }).catch(() => undefined); }, 150); } } };
app.post("/api/code/run", async (req, res) => { const { language, code, input = "" } = req.body as { language?: string; code?: string; input?: string }; if (!language || !code || !languageConfig[language]) return res.status(400).json({ message: "Supported language and non-empty code are required" }); if (code.length > 100_000 || input.length > 20_000) return res.status(413).json({ message: "Code or input exceeds the safe size limit" }); const config = languageConfig[language]; const started = Date.now(); const container = `skillsync-run-${Date.now()}`; try { const args = ["run", "--rm", "--name", container, "--network", "none", "--memory", "128m", "--cpus", "0.5", "--pids-limit", "64", "--read-only", "--tmpfs", "/tmp:rw,noexec,nosuid,size=32m", "-i", "-v", `${process.cwd()}:/host:ro`, config.image, ...config.command]; const result = await runFile("docker", args, { input: `${code}\n${input}`, timeout: 5000, maxBuffer: 200_000 }); const executionTime = Date.now() - started; void prisma.codeRun.create({ data: { studentId: userIdFromRequest(req), language, status: "SUCCESS", executionTimeMs: executionTime } }).catch(() => undefined); res.json({ status: "SUCCESS", output: result.stdout, error: result.stderr, executionTime }); } catch (error) { const message = error instanceof Error ? error.message : "Execution failed"; if (message.includes("ENOENT") && process.env.NODE_ENV !== "production") { try { const result = await runLocalCode(language, code, input); const executionTime = Date.now() - started; void prisma.codeRun.create({ data: { studentId: userIdFromRequest(req), language, status: "SUCCESS", executionTimeMs: executionTime } }).catch(() => undefined); return res.json({ status: "SUCCESS", output: result.stdout, error: result.stderr, executionTime, runner: "local-development" }); } catch (localError) { const localMessage = localError instanceof Error ? localError.message : "Local execution failed"; const errorText = localMessage.includes("timed out") ? "Time limit exceeded." : localMessage; const executionTime = Date.now() - started; void prisma.codeRun.create({ data: { studentId: userIdFromRequest(req), language, status: "FAILED", executionTimeMs: executionTime } }).catch(() => undefined); return res.status(422).json({ status: "FAILED", output: "", error: errorText, executionTime, runner: "local-development" }); } } const unavailable = message.includes("ENOENT") ? "Docker is not available. Start Docker Desktop to run code securely." : message.includes("timed out") ? "Time limit exceeded." : "Compilation or runtime error."; const executionTime = Date.now() - started; void prisma.codeRun.create({ data: { studentId: userIdFromRequest(req), language, status: unavailable.includes("Docker") ? "UNAVAILABLE" : "FAILED", executionTimeMs: executionTime } }).catch(() => undefined); res.status(422).json({ status: unavailable.includes("Docker") ? "UNAVAILABLE" : "FAILED", output: "", error: unavailable, executionTime }); } });
app.get("/api/dev/data", (_req, res) => { if (process.env.NODE_ENV === "production") return res.status(404).json({ message: "Not found" }); res.json({ storage: process.env.DATABASE_URL ? "postgresql" : "local-development-store", users: [...localUsers.values()].map(({ passwordHash: _passwordHash, ...user }) => user), note: "Development-only view. Password hashes are intentionally hidden." }); });
const emptyCodeActivity = () => { const heatmap = []; for (let index = 364; index >= 0; index -= 1) { const date = new Date(); date.setHours(0, 0, 0, 0); date.setDate(date.getDate() - index); heatmap.push({ date: date.toISOString().slice(0, 10), count: 0 }); } return { heatmap, currentStreak: 0, longestStreak: 0, totalRuns: 0, successRate: 0, byLanguage: [] }; };
const aggregateCodeActivity = (runs: { language: string; status: string; createdAt: Date }[]) => { const counts = new Map<string, number>(); const languages = new Map<string, number>(); runs.forEach((run) => { const date = run.createdAt.toISOString().slice(0, 10); counts.set(date, (counts.get(date) ?? 0) + 1); languages.set(run.language, (languages.get(run.language) ?? 0) + 1); }); const heatmap = []; for (let index = 364; index >= 0; index -= 1) { const date = new Date(); date.setHours(0, 0, 0, 0); date.setDate(date.getDate() - index); heatmap.push({ date: date.toISOString().slice(0, 10), count: counts.get(date.toISOString().slice(0, 10)) ?? 0 }); } const active = new Set(heatmap.filter((day) => day.count > 0).map((day) => day.date)); const today = new Date(); today.setHours(0, 0, 0, 0); const cursor = active.has(today.toISOString().slice(0, 10)) ? today : new Date(today.getTime() - 86400000); let currentStreak = 0; while (active.has(cursor.toISOString().slice(0, 10))) { currentStreak += 1; cursor.setDate(cursor.getDate() - 1); } let longestStreak = 0; let running = 0; heatmap.forEach((day) => { running = day.count ? running + 1 : 0; longestStreak = Math.max(longestStreak, running); }); return { heatmap, currentStreak, longestStreak, totalRuns: runs.length, successRate: runs.length ? Math.round(runs.filter((run) => run.status === "SUCCESS").length / runs.length * 100) : 0, byLanguage: [...languages.entries()].map(([language, count]) => ({ language, count })) }; };
app.get("/api/code/activity", async (req, res) => { if (!process.env.DATABASE_URL) return res.json(emptyCodeActivity()); const since = new Date(); since.setHours(0, 0, 0, 0); since.setDate(since.getDate() - 364); const runs = await prisma.codeRun.findMany({ where: { studentId: userIdFromRequest(req), createdAt: { gte: since } }, select: { language: true, status: true, createdAt: true }, orderBy: { createdAt: "asc" } }); res.json(aggregateCodeActivity(runs)); });
app.post("/api/auth/signup", async (req, res) => { const data = signupSchema.parse(req.body); const exists = await prisma.user.findUnique({ where: { email: data.email } }); if (exists) return res.status(409).json({ message: "Email already registered" }); const user = await prisma.user.create({ data: { name: data.name, email: data.email, passwordHash: await bcrypt.hash(data.password, 12), role: data.role } }); setAuthCookies(res, user); res.status(201).json({ user: { id: user.id, name: user.name, email: user.email, role: user.role } }); });
app.post("/api/auth/login", async (req, res) => { const data = loginSchema.parse(req.body); const user = await prisma.user.findUnique({ where: { email: data.email } }); if (!user?.passwordHash || !(await bcrypt.compare(data.password, user.passwordHash))) return res.status(401).json({ message: "Invalid credentials" }); setAuthCookies(res, user); res.json({ user: { id: user.id, name: user.name, email: user.email, role: user.role } }); });
app.get("/api/auth/me", async (req, res) => { const token = cookieValue(req, "accessToken"); if (!token) return res.status(401).json({ message: "Authentication required" }); try { const payload = jwt.verify(token, secret) as { sub: string }; const user = await prisma.user.findUnique({ where: { id: payload.sub }, select: { id: true, name: true, email: true, role: true } }); if (!user) return res.status(401).json({ message: "Session invalid" }); res.json({ user }); } catch { res.status(401).json({ message: "Session expired" }); } });
app.post("/api/auth/refresh", async (req, res) => { const token = cookieValue(req, "refreshToken"); if (!token) return res.status(401).json({ message: "Refresh token missing" }); try { const payload = jwt.verify(token, refreshSecret) as { sub: string; role: Role }; const user = await prisma.user.findUnique({ where: { id: payload.sub }, select: { id: true, role: true } }); if (!user) return res.status(401).json({ message: "Session invalid" }); setAuthCookies(res, user); res.json({ refreshed: true }); } catch { res.status(401).json({ message: "Refresh token expired" }); } });
app.post("/api/auth/logout", async (_req, res) => { res.setHeader("Set-Cookie", ["accessToken=; HttpOnly; Path=/; Max-Age=0", "refreshToken=; HttpOnly; Path=/; Max-Age=0"]); res.json({ loggedOut: true }); });
const userIdFromRequest = (req: express.Request) => String(req.headers["x-user-id"] ?? "demo-student");
const skillCatalog = ["TypeScript", "React", "Next.js", "Node.js", "Python", "SQL", "PostgreSQL", "Docker", "AWS", "System Design", "Communication", "Git"];
const extractSkills = (text: string) => skillCatalog.filter((skill) => text.toLowerCase().includes(skill.toLowerCase()));
const skillBadges = [{ key: "typescript-verified", name: "TypeScript Verified", icon: "🔷", description: "Verified TypeScript capability", skillName: "TypeScript" }, { key: "react-verified", name: "React Verified", icon: "⚛️", description: "Verified React capability", skillName: "React" }, { key: "python-verified", name: "Python Verified", icon: "🐍", description: "Verified Python capability", skillName: "Python" }, { key: "sql-verified", name: "SQL Verified", icon: "🗄️", description: "Verified SQL capability", skillName: "SQL" }, { key: "aws-verified", name: "AWS Verified", icon: "☁️", description: "Verified AWS capability", skillName: "AWS" }, { key: "docker-verified", name: "Docker Verified", icon: "🐳", description: "Verified Docker capability", skillName: "Docker" }, { key: "system-design-verified", name: "System Design Verified", icon: "🏗️", description: "Verified system design capability", skillName: "System Design" }, { key: "communication-verified", name: "Communication Verified", icon: "💬", description: "Verified communication capability", skillName: "Communication" }, { key: "git-verified", name: "Git Verified", icon: "🌿", description: "Verified Git capability", skillName: "Git" }];
const verifySkills = async (studentId: string, skills: string[], sourceType: string) => { const known = skillBadges.filter((badge) => skills.some((skill) => skill.toLowerCase() === badge.skillName.toLowerCase())); const awarded = []; for (const badge of known) { await prisma.studentSkill.upsert({ where: { studentId_skill: { studentId, skill: badge.skillName } }, update: { level: "EXPERT", score: 100, verified: true }, create: { studentId, skill: badge.skillName, level: "EXPERT", score: 100, verified: true } }); const result = await prisma.studentBadge.upsert({ where: { studentId_badgeId: { studentId, badgeId: (await prisma.skillBadge.findUniqueOrThrow({ where: { key: badge.key } })).id } }, update: {}, create: { studentId, badgeId: (await prisma.skillBadge.findUniqueOrThrow({ where: { key: badge.key } })).id, sourceType }, include: { badge: true } }); if (result.earnedAt.getTime() >= Date.now() - 1000) awarded.push(result.badge); } return awarded; };
