app.post("/api/ai/resume/analyze", upload.single("resume"), async (req, res) => {
  if (!req.file) return res.status(400).json({ message: "A resume file is required" });
  const text = `${req.file.originalname} ${String(req.body.text ?? "")}`;
  const skills = extractSkills(text); const missing = skillCatalog.filter((skill) => !skills.includes(skill));
  if (process.env.DATABASE_URL) await verifySkills(userIdFromRequest(req), skills, "RESUME_VERIFIED");
  const result = report("RESUME", "Resume intelligence report", { atsScore: Math.min(96, 48 + skills.length * 4), roleMatch: Math.min(94, 35 + skills.length * 5), skills, missingSkills: missing.slice(0, 6), education: [], projects: [], experience: [] });
  res.status(201).json(result);
});
