const calculateBridgeMatch = (job: typeof bridgeJobs[number]) => { const matched = job.required.filter((skill) => bridgeStudentSkills.includes(skill)); const missing = job.required.filter((skill) => !bridgeStudentSkills.includes(skill)); const skillMatch = Math.round(matched.length / job.required.length * 100); return { job, overall: Math.max(0, skillMatch - missing.length * 3 + 8), skillMatch, technical: skillMatch, project: job.projects ? 82 : 55, certification: job.certifications ? 70 : 58, experience: 72, missing: missing.map((skill) => ({ skill, priority: matched.length < 2 ? "CRITICAL" : "IMPORTANT", category: "TECHNICAL" })) }; };
